WHERE slug = 'vibrators' AND guide_ar = '' AND faqs_ar = '[]'::jsonb;

-- Verification: every row with its Arabic character count and FAQ count.
-- Expect 23 rows, guide_ar_chars above 0 and faqs_ar = 3 or 4 everywhere
-- (a row you had already written by hand keeps its own values).
SELECT slug, length(guide_ar) AS guide_ar_chars, jsonb_array_length(faqs_ar) AS faqs_ar
FROM public.category_editorial
ORDER BY slug;

